FONT='C:/Windows/Fonts/segoeui.ttf'; BOLD='C:/Windows/Fonts/segoeuib.ttf'
def wrap(draw,text,font,width):
 words=text.split();lines=[];line=''
 for word in words:
  candidate=(line+' '+word).strip()
  if draw.textlength(candidate,font=font)>width and line:lines.append(line);line=word
  else:line=candidate
 if line:lines.append(line)
 return lines
def card(ch,sc,n,total):
 im=Image.new('RGB',(1920,1080),'#0b100d');d=ImageDraw.Draw(im)
 d.text((56,38),'RTS AI / APP WALKTHROUGHS',font=ImageFont.truetype(BOLD,22),fill='#a5b6aa')
 d.text((56,88),ch['title'],font=ImageFont.truetype(BOLD,42),fill='#efd096')
 source=OUT/sc['asset']
 if not source.exists():raise FileNotFoundError(source)
 pic=Image.open(source).convert('RGB');pic.thumbnail((1200,758));x=56+(1200-pic.width)//2;y=206+(758-pic.height)//2;im.paste(pic,(x,y));d.rectangle((54,204,1258,966),outline='#354b3c',width=2)
 f=ImageFont.truetype(BOLD,34);y=216
 for line in wrap(d,sc['title'],f,552):d.text((1300,y),line,font=f,fill='#efd096');y+=47
 y+=34;f=ImageFont.truetype(FONT,28)
 for b in sc['bullets']:
  d.ellipse((1300,y+12,1310,y+22),fill='#8bd6a1')
  for line in wrap(d,b,f,505):d.text((1324,y),line,font=f,fill='#e2eae3');y+=40
  y+=23
 d.text((1300,865),'RECOMMENDATION' if 'Recommended' in sc['title'] or ch['id'].startswith('09') else 'CURRENT LOCAL BUILD',font=ImageFont.truetype(BOLD,20),fill='#8bd6a1')
 d.text((56,1011),'Actual app captures | Local narration | 9 October 2026',font=ImageFont.truetype(FONT,21),fill='#9aafa0')
 d.text((1610,1011),f'{n+1:02d} / {total:02d}',font=ImageFont.truetype(BOLD,22),fill='#9aafa0')
 return im
ffmpeg=shutil.which('ffmpeg');probe=shutil.which('ffprobe');results=[]
only=__import__('os').environ.get('TOUR_CHAPTER')
if only and (OUT/'render-results.json').exists():results=json.loads((OUT/'render-results.json').read_text())
for ch in manifest:
 if only and ch['id']!=only:continue
 parts=[];duration=0;srt=[];transcript=[]
 for n,sc in enumerate(ch['scenes']):
  stem=OUT/'sources'/f"{ch['id']}-{n+1}";image=str(stem)+'.png';wav=str(stem)+'.wav';segment=str(stem)+'.mp4'
  card(ch,sc,n,len(ch['scenes'])).save(image)
  textfile=str(stem)+'.txt';pathlib.Path(textfile).write_text(sc['narration'],encoding='utf-8-sig')
  # Reuse approved neural speech; never fall back to the rejected system voice.
  neural=OUT/'neural'/f"{ch['id']}-{n+1}.wav"
  if not neural.exists():raise RuntimeError('Generate local neural narration with video-tour-revoice.py first.')
  shutil.copy2(neural,wav)
  length=float(subprocess.check_output([probe,'-v','error','-show_entries','format=duration','-of','csv=p=0',wav]).decode().strip())+0.65
  inputs=['-loop','1','-i',image,'-i',wav];filters=['-vf','fps=24,format=yuv420p']
  live=OUT/'sources/gameplay-clip.mp4'
  if sc['asset']=='sources/gameplay-end.png' and live.exists():
   inputs+=['-stream_loop','-1','-i',str(live)];filters=['-filter_complex','[2:v]scale=1200:675[live];[0:v][live]overlay=56:247,fps=24,format=yuv420p[out]','-map','[out]','-map','1:a']
  subprocess.run([ffmpeg,'-hide_banner','-loglevel','error','-y',*inputs,'-t',str(length),*filters,'-c:v','libx264','-preset','veryfast','-crf','23','-c:a','aac','-b:a','128k','-af','apad','-movflags','+faststart',segment],check=True)
  def stamp(s):
   ms=round(s*1000);h,ms=divmod(ms,3600000);m,ms=divmod(ms,60000);sec,ms=divmod(ms,1000);return f'{h:02}:{m:02}:{sec:02},{ms:03}'
  sentences=sc['narration'].split('. ');cursor=duration;words=sum(len(s.split()) for s in sentences)
  for sentence in sentences:
   end=cursor+(length-.65)*len(sentence.split())/words;srt.append(f'{len(srt)+1}\n{stamp(cursor)} --> {stamp(end)}\n{sentence.strip()}\n');cursor=end
  transcript.append(f"## {sc['title']}\n\n{sc['narration']}\n");duration+=length;parts.append(segment)
  print('Rendered',ch['id'],n+1,flush=True)
 concat=OUT/'sources'/f"{ch['id']}-concat.txt";concat.write_text('\n'.join("file '"+str(pathlib.Path(p).as_posix())+"'" for p in parts),encoding='utf8')
 target=OUT/f"{ch['id']}.mp4";subprocess.run([ffmpeg,'-hide_banner','-loglevel','error','-y','-f','concat','-safe','0','-i',str(concat),'-c','copy','-movflags','+faststart',str(target)],check=True)
 (OUT/f"{ch['id']}.srt").write_text('\n'.join(srt),encoding='utf8')
 (OUT/f"{ch['id']}.md").write_text('# '+ch['title']+'\n\n'+'\n'.join(transcript),encoding='utf8')
 results=[r for r in results if r['id']!=ch['id']]
 results.append({'id':ch['id'],'title':ch['title'],'duration':round(duration,2),'file':target.name,'bytes':target.stat().st_size})
 results.sort(key=lambda r:r['id'])
 (OUT/'render-results.json').write_text(json.dumps(results,indent=2),encoding='utf8')
print('All narrated chapters rendered.',flush=True)
